integrity_keywords := {"checksum", "hash", "signature", "verify", "integrity", "gpgcheck"}
package_keywords := {"package", "artifact", "version", "name"}

check_insecure_protocol(value) {
    value.ir_type == "String"
    regex.match("(?i)^(http|ftp|telnet|smtp)://", value.value)
} else {
    value.ir_type == "Sum"
    regex.match("(?i)^(http|ftp|telnet|smtp)://", value.code)
}

# Helper function to recursively find all attributes in a node, including nested Hash/Array structures
find_all_attributes(node) = attrs {
    attrs := {attr |
        walk(node, [path, n])
        n.ir_type == "Attribute"
        attr := n
    }
}

# Helper function to find key-value pairs in Hash structures
find_hash_pairs(node) = pairs {
    pairs := {pair |
        walk(node, [path, n])
        n.ir_type == "Hash"
        item := n.value[_]
        pair := {"name": item.key.value, "value": item.value}
    }
}

# Combined function to get all attributes including nested ones
get_all_attributes(node) = attrs {
    attrs := find_all_attributes(node) | find_hash_pairs(node)
}

