    walk(node, [path, value])
    value.ir_type == "String"
    regex.match("(?i)^(http://|ftp://|telnet://|smtp://)", value.value)
} else {
    walk(node, [path, value])
    value.ir_type == "Sum"
    regex.match("(?i)^(http://|ftp://|telnet://|smtp://)", value.code)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    all_attrs := get_all_attributes(parent)
    attr := all_attrs[_]
    protocol_keywords[attr.name]
    check_insecure_protocol(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Use of insecure protocol without integrity checks. (CWE-353)"
    }
}

